8: /**
9:  * A simple CSS formatter to make the AI-generated CSS more readable.
10:  * It adds indentation and newlines to a minified CSS string.
11:  * @param css The raw CSS string.
12:  * @returns A formatted CSS string.
13:  */
14: const formatAdvancedCss = (css: string): string => {
15:     if (!css) return '';
16:     let formatted = css;
17:     // Add new lines for structure. This makes each selector, rule, and brace its own line.
18:     formatted = formatted.replace(/\s*([{};])\s*/g, '$1\n');
19:     // Remove any blank lines that might have been created.
20:     formatted = formatted.replace(/^\s*[\r\n]/gm, '');
21: 
22:     const lines = formatted.split('\n');
23:     let indentLevel = 0;
24:     const indent = '  '; // 2-space indentation
25:     let result = '';
26: 
27:     for (const line of lines) {
28:         const trimmed = line.trim();
29:         if (!trimmed) continue;
30:         
31:         // Decrease indent level for closing braces BEFORE printing the line.
32:         if (trimmed.startsWith('}')) {
33:             indentLevel = Math.max(0, indentLevel - 1);
34:         }
35:         
36:         result += indent.repeat(indentLevel) + trimmed + '\n';
37:         
38:         // Increase indent level for opening braces AFTER printing the line.
39:         if (trimmed.endsWith('{')) {
40:             indentLevel++;
41:         }
42:     }
43:     // Add a final newline for spacing in the output panel.
44:     return result + '\n';
45: };
